    /**
     * @method
     * @name indodax#fetchOrderBook
     * @description fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
     * @see https://github.com/btcid/indodax-official-api-docs/blob/master/Public-RestAPI.md#depth
     * @param {string} symbol unified symbol of the market to fetch the order book for
     * @param {int} [limit] the maximum amount of order book entries to return
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
     */
    public CompletableFuture<OrderBook> fetchOrderBook(Object symbol, Long limit, Map<String, Object> parameters)
    {

        return BaseExchange.supplyAsync(() -> {

            if (java.util.Objects.equals(this.markets, null))
            {
                (this.loadMarkets(false, new HashMap<String, Object>() {{}})).join();
            }
            Map<String, Object> market = (Map<String, Object>) this.market(symbol);
            Map<String, Object> request = new HashMap<String, Object>() {{
                put( "pair", ((Map<String, Object>)market).get("id") );
            }};
            Map<String, Object> orderbook = (this.publicGetApiDepthPair(this.extend(request, parameters))).join();
            return this.parseOrderBook(orderbook, ((Map<String, Object>)market).get("symbol"), (Long) null, "buy", "sell", 0, 1, 2);
        }).thenApply(OrderBook::new);

    }

    public Object parseTicker(Object ticker, Map<String, Object> market)
    {
        //
        //     {
        //         "high":"0.01951",
        //         "low":"0.01877",
        //         "vol_eth":"39.38839319",
        //         "vol_btc":"0.75320886",
        //         "last":"0.01896",
        //         "buy":"0.01896",
        //         "sell":"0.019",
        //         "server_time":1565248908
        //     }
        //
        String symbol = this.safeSymbol(null, market, (String) null, (String) null);
        Long timestamp = this.safeTimestamp(ticker, "server_time");
        String baseVolume = ("vol_" + this.safeStringLower(market, "baseId"));
        String quoteVolume = ("vol_" + this.safeStringLower(market, "quoteId"));
        String last = this.safeString(ticker, "last");
        return this.safeTicker(new HashMap<String, Object>() {{
            put( "symbol", symbol );
            put( "timestamp", timestamp );
            put( "datetime", Indodax.this.iso8601(timestamp) );
            put( "high", Indodax.this.safeString(ticker, "high") );
            put( "low", Indodax.this.safeString(ticker, "low") );
            put( "bid", Indodax.this.safeString(ticker, "buy") );
            put( "bidVolume", null );
            put( "ask", Indodax.this.safeString(ticker, "sell") );
            put( "askVolume", null );
            put( "vwap", null );
            put( "open", null );
            put( "close", last );
            put( "last", last );
            put( "previousClose", null );
            put( "change", null );
            put( "percentage", null );
            put( "average", null );
            put( "baseVolume", Indodax.this.safeString(ticker, baseVolume) );
            put( "quoteVolume", Indodax.this.safeString(ticker, quoteVolume) );
            put( "info", ticker );
        }}, market);
    }

